    val Panel = Color(0xFF15100F)   // #15100F  menu panel (HedRoom --tint)
    val Line = Color(0xFF2B1C18)   // #2B1C18  panel border, tile outlines, dividers; decorative
    val Key = Color(0xFF4A3229)   // #4A3229  keycap outline; decorative
    val Track = Color(0xFF2A1512)   // #2A1512  empty download track
    val Ember = Color(0xFFB8443C)   // #B8443C  accent: focus ring, dots, progress; NEVER text
    val Text = Color(0xFFAD7A5B)   // #AD7A5B  primary text, peak in-app luminance 0.2356
    val Text2 = Color(0xFFA67253)   // #A67253  secondary text on ground/panel only; never inside a focused item
    val FocusFill = Color(0xFF2C1715)   // #2C1715  ember 14% over panel, stored solid
}

/** Launcher-only colours (icon, banner). Never inside the app: navy and white are too cool/bright at night. */
object BrandLauncher {
    val Navy = Color(0xFF163065)   // #163065
    val White = Color(0xFFFFFFFF)   // #FFFFFF
    val Dot = Color(0xFFD9776D)   // #D9776D
}

/**
 * Archivo (Latin, BeFeast brand face) with Inter as a named Cyrillic fallback (Archivo has no Cyrillic).
 *
 * API 29+: Typeface.CustomFallbackBuilder builds one Typeface per weight (Archivo -> Inter -> system
 * sans-serif), so a Russian title renders in Inter instead of Roboto. Compose uses a wrapped platform
 * Typeface as-is and does not pick a weight inside it, so every weight gets its own FontFamily and
 * BrandType pairs each style with the family of its weight.
 * API 28: one resource FontFamily with real 300/400/600 files; Cyrillic then falls back to the system sans.
 */
object BrandFonts {
    val Weights = listOf(300, 400, 600)

    /** weight -> FontFamily that renders that weight. */
    fun families(context: Context): Map<Int, FontFamily> =
        if (Build.VERSION.SDK_INT >= 29) {
            // App lane: a failing fallback chain must never take the night UI down; Archivo alone still works.
            Weights.associateWith { runCatching { chained(context, it) }.getOrElse { _ -> plain } }
        } else {
            Weights.associateWith { plain }
        }

    private val plain = FontFamily(
        Font(R.font.archivo_light, FontWeight(300)),
        Font(R.font.archivo_regular, FontWeight(400)),
        Font(R.font.archivo_semibold, FontWeight(600)),
    )

    @RequiresApi(29)
    private fun chained(context: Context, weight: Int): FontFamily {
        val res = context.resources
        fun fam(vararg fonts: Pair<Int, Int>): android.graphics.fonts.FontFamily {
            val b = android.graphics.fonts.FontFamily.Builder(
                android.graphics.fonts.Font.Builder(res, fonts[0].first).setWeight(fonts[0].second).build()
            )
            for ((id, w) in fonts.drop(1)) {
                b.addFont(android.graphics.fonts.Font.Builder(res, id).setWeight(w).build())
            }
            return b.build()
        }
        val archivo = fam(R.font.archivo_light to 300, R.font.archivo_regular to 400, R.font.archivo_semibold to 600)
        val inter = fam(
            R.font.inter_cyrillic_light to 300, R.font.inter_cyrillic_regular to 400, R.font.inter_cyrillic_semibold to 600,
        )
        val typeface = android.graphics.Typeface.CustomFallbackBuilder(archivo)
            .addCustomFallback(inter)
            .setSystemFallback("sans-serif")
            .setStyle(android.graphics.fonts.FontStyle(weight, android.graphics.fonts.FontStyle.FONT_SLANT_UPRIGHT))
            .build()
        return FontFamily(androidx.compose.ui.text.font.Typeface(typeface))
    }
}

/**
 * Type scale for 1920x1080 at 3 m (px / 2). Minimum essential text 12 sp = 24 px.
 * Compose has no text-transform: uppercase Eyebrow and Keycap strings in code. Eyebrow letterSpacing
 * is 0.18 em. Focus swaps the weight with focused(style) and never the colour.
 */
class BrandType(private val families: Map<Int, FontFamily>) {
    private fun f(weight: Int): FontFamily = families.getValue(weight)

    val Title = TextStyle(
        fontFamily = f(300), fontWeight = FontWeight(300), fontSize = 52.sp,
        lineHeight = 55.1.sp, letterSpacing = -0.02.em, color = BrandColors.Text,
        fontSynthesis = FontSynthesis.None,
    )
    val Artist = TextStyle(
        fontFamily = f(400), fontWeight = FontWeight(400), fontSize = 18.sp,
        lineHeight = 22.5.sp, letterSpacing = 0.em, color = BrandColors.Text2,
        fontSynthesis = FontSynthesis.None,
    )
    val Eyebrow = TextStyle(
        fontFamily = f(600), fontWeight = FontWeight(600), fontSize = 12.sp,
        lineHeight = 12.0.sp, letterSpacing = 0.18.em, color = BrandColors.Text2,
        fontSynthesis = FontSynthesis.None,
    )
    val Time = TextStyle(
        fontFamily = f(300), fontWeight = FontWeight(300), fontSize = 44.sp,
        lineHeight = 44.0.sp, letterSpacing = -0.01.em, color = BrandColors.Text2,
        fontSynthesis = FontSynthesis.None,
        fontFeatureSettings = "tnum",
    )
    val TimeLabel = TextStyle(
        fontFamily = f(400), fontWeight = FontWeight(400), fontSize = 13.sp,
        lineHeight = 17.9.sp, letterSpacing = 0.em, color = BrandColors.Text2,
        fontSynthesis = FontSynthesis.None,
    )
    val Hint = TextStyle(
        fontFamily = f(400), fontWeight = FontWeight(400), fontSize = 12.sp,
        lineHeight = 12.0.sp, letterSpacing = 0.em, color = BrandColors.Text2,
        fontSynthesis = FontSynthesis.None,
    )
    val Keycap = TextStyle(
        fontFamily = f(600), fontWeight = FontWeight(600), fontSize = 12.sp,
        lineHeight = 12.0.sp, letterSpacing = 0.04.em, color = BrandColors.Text2,
        fontSynthesis = FontSynthesis.None,
    )
    val MenuFigure = TextStyle(
        fontFamily = f(300), fontWeight = FontWeight(300), fontSize = 36.sp,
        lineHeight = 36.0.sp, letterSpacing = -0.01.em, color = BrandColors.Text,
        fontSynthesis = FontSynthesis.None,
        fontFeatureSettings = "tnum",
    )
    val MenuUnit = TextStyle(
        fontFamily = f(400), fontWeight = FontWeight(400), fontSize = 13.sp,
        lineHeight = 13.0.sp, letterSpacing = 0.em, color = BrandColors.Text,
        fontSynthesis = FontSynthesis.None,
    )
    val MenuRow = TextStyle(
        fontFamily = f(400), fontWeight = FontWeight(400), fontSize = 16.sp,
        lineHeight = 19.2.sp, letterSpacing = 0.em, color = BrandColors.Text,
        fontSynthesis = FontSynthesis.None,
    )
    val MenuMeta = TextStyle(
        fontFamily = f(400), fontWeight = FontWeight(400), fontSize = 12.sp,
        lineHeight = 14.4.sp, letterSpacing = 0.em, color = BrandColors.Text,
        fontSynthesis = FontSynthesis.None,
    )
    val MenuSub = TextStyle(
        fontFamily = f(400), fontWeight = FontWeight(400), fontSize = 14.sp,
        lineHeight = 18.9.sp, letterSpacing = 0.em, color = BrandColors.Text2,
        fontSynthesis = FontSynthesis.None,
    )
    val Headline = TextStyle(
        fontFamily = f(300), fontWeight = FontWeight(300), fontSize = 36.sp,
        lineHeight = 38.9.sp, letterSpacing = -0.015.em, color = BrandColors.Text,
        fontSynthesis = FontSynthesis.None,
    )
    val Percent = TextStyle(
        fontFamily = f(300), fontWeight = FontWeight(300), fontSize = 56.sp,
        lineHeight = 56.0.sp, letterSpacing = -0.01.em, color = BrandColors.Text2,
        fontSynthesis = FontSynthesis.None,
        fontFeatureSettings = "tnum",
    )
    val Caption = TextStyle(
        fontFamily = f(400), fontWeight = FontWeight(400), fontSize = 13.sp,
        lineHeight = 18.2.sp, letterSpacing = 0.em, color = BrandColors.Text2,
        fontSynthesis = FontSynthesis.None,
    )

    /** Focused variant of a menu style: weight 600, same size, same colour (see BrandFocus). */
    fun focused(style: TextStyle): TextStyle = style.copy(fontFamily = f(600), fontWeight = FontWeight(600))
}

@Composable
fun rememberBrandType(): BrandType {
    val context = LocalContext.current
    return remember { BrandType(BrandFonts.families(context.applicationContext)) }
}

/** Focus = ring + fill + weight. Never brightness, never scale, never glow. */
object BrandFocus {
    val RingWidth = 2.dp                 // 4 px, drawn inset
    val Ring = BrandColors.Ember
    val Fill = BrandColors.FocusFill
    val FigureWeight = FontWeight(600)   // from 300; apply with type.focused(type.MenuFigure)
    val LabelWeight = FontWeight(600)    // from 400; apply with type.focused(type.MenuRow)
    const val Scale = 1f                 // tv-material: ClickableSurfaceDefaults.scale(focusedScale = 1f)
}

